window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-984132ff2743e936"]={"versions": [{"id": "FIG-984132ff2743e936", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm zur Darstellung des standardisierten ISO/OSI-7-Schichten-Referenzmodells im Kontext des AUTOSAR-ECU-Ressourcenmodells (AUTOSAR_ResourceTemplateECU). Es veranschaulicht die hierarchische Einordnung und Abstraktionsebenen von Kommunikationsprotokollen für Steuergeräte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst sieben vertikal übereinander angeordnete Schichtenblöcke:</p>\n<ul class=\"fig-list\"><li><code>Application layer</code> (Schicht 7): Anwendungsebene\n</li><li><code>Presentation layer</code> (Schicht 6): Darstellungsebene\n</li><li><code>Session layer</code> (Schicht 5): Sitzungsebene\n</li><li><code>Transport layer</code> (Schicht 4): Transportschicht\n</li><li><code>Network layer</code> (Schicht 3): Vermittlungsschicht\n</li><li><code>Data link layer</code> (Schicht 2): Sicherungsschicht\n</li><li><code>Physical layer</code> (Schicht 1): Bitübertragungsschicht\n</li></ul>\n<p class=\"fig-p\">Jeweils benachbarte Schichten sind über vertikale Pfeilschnittstellen bidirektional gekoppelt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der vertikale Datenfluss erfolgt über zwei gerichtete Kommunikationspfade zwischen direkt benachbarten Schichten:</p>\n<ul class=\"fig-list\"><li>Abwärtsgerichteter Pfad (Sende-/Downlink-Richtung): Pfeile weisen auf der linken Seite jeweils von der höheren zur darunterliegenden Schicht (<code>Application layer</code> abwärts bis <code>Physical layer</code>).\n</li><li>Aufwärtsgerichteter Pfad (Empfangs-/Uplink-Richtung): Pfeile weisen auf der rechten Seite jeweils von der unteren zur darüberliegenden Schicht (<code>Physical layer</code> aufwärts bis <code>Application layer</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als informatives Referenzmodell für die Zuordnung von Netzwerk- und Busprotokollen, Kommunikationscontrollern sowie Hardware-/Treiber-Ressourcen im ECU-Resource-Template. Kommunikationsrelevante ECU-Ressourcen und AUTOSAR-Basissoftware- bzw. Hardware-Abstraktionsmodule können gegen diese logischen ISO/OSI-Schichten abgebildet und klassifiziert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-612be74a4e90ef29", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm zur Darstellung des standardisierten ISO/OSI-7-Schichten-Referenzmodells im Kontext des AUTOSAR-ECU-Ressourcenmodells (AUTOSAR_ResourceTemplateECU). Es veranschaulicht die hierarchische Einordnung und Abstraktionsebenen von Kommunikationsprotokollen für Steuergeräte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst sieben vertikal übereinander angeordnete Schichtenblöcke:</p>\n<ul class=\"fig-list\"><li><code>Application layer</code> (Schicht 7): Anwendungsebene\n</li><li><code>Presentation layer</code> (Schicht 6): Darstellungsebene\n</li><li><code>Session layer</code> (Schicht 5): Sitzungsebene\n</li><li><code>Transport layer</code> (Schicht 4): Transportschicht\n</li><li><code>Network layer</code> (Schicht 3): Vermittlungsschicht\n</li><li><code>Data link layer</code> (Schicht 2): Sicherungsschicht\n</li><li><code>Physical layer</code> (Schicht 1): Bitübertragungsschicht\n</li></ul>\n<p class=\"fig-p\">Jeweils benachbarte Schichten sind über vertikale Pfeilschnittstellen bidirektional gekoppelt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der vertikale Datenfluss erfolgt über zwei gerichtete Kommunikationspfade zwischen direkt benachbarten Schichten:</p>\n<ul class=\"fig-list\"><li>Abwärtsgerichteter Pfad (Sende-/Downlink-Richtung): Pfeile weisen auf der linken Seite jeweils von der höheren zur darunterliegenden Schicht (<code>Application layer</code> abwärts bis <code>Physical layer</code>).\n</li><li>Aufwärtsgerichteter Pfad (Empfangs-/Uplink-Richtung): Pfeile weisen auf der rechten Seite jeweils von der unteren zur darüberliegenden Schicht (<code>Physical layer</code> aufwärts bis <code>Application layer</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als informatives Referenzmodell für die Zuordnung von Netzwerk- und Busprotokollen, Kommunikationscontrollern sowie Hardware-/Treiber-Ressourcen im ECU-Resource-Template. Kommunikationsrelevante ECU-Ressourcen und AUTOSAR-Basissoftware- bzw. Hardware-Abstraktionsmodule können gegen diese logischen ISO/OSI-Schichten abgebildet und klassifiziert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-984132ff2743e936", "to": "FIG-612be74a4e90ef29", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
